// Lead website if given, else https://<email domain>. Free mail domains say nothing about the company: no fetch.
const FREE_MAIL = ['gmail', 'yahoo', 'outlook', 'hotmail', 'icloud', 'aol', 'proton', 'live', 'ymail'];
const body = $input.first().json.body || {};
const domain = String(body.email_domain || '').trim().toLowerCase();
let url = String(body.website || '').trim();
if (!url && domain && !FREE_MAIL.some(f => domain.startsWith(f))) url = 'https://' + domain;
if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url;
return [{ json: { company: String(body.company || '').trim(), domain, url } }];

// Website HTML -> plain text (max 6000 chars), then the Gemini request body.
const lead = $('Pick URL').first().json;
const html = String($input.first().json.data || '');
const text = html
  .replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#?\w+;/g, ' ')
  .replace(/\s+/g, ' ').trim().slice(0, 6000);
const usable = text.length >= 200;  // less than this is usually a block page or an empty JS shell
const prompt = 'You research companies for a BPO (call center outsourcing) sales team.\n'
  + 'Company name: ' + (lead.company || 'unknown') + '\n'
  + 'Domain: ' + (lead.domain || 'unknown') + '\n'
  + 'Website text: ' + (usable ? text : 'website unreadable') + '\n\n'
  + 'Answer with STRICT JSON only, no other text, exactly these keys:\n'
  + '{"industry": one of "ecommerce", "finance", "healthcare", "telecom", "tech", "other", "unknown",\n'
  + ' "summary": one or two sentences on what the company does,\n'
  + ' "support_channels": short comma list of customer support channels, e.g. "phone, chat, email", or "unknown",\n'
  + ' "company_size": short estimate, e.g. "200-500 employees", or "unknown",\n'
  + ' "source": "' + (usable ? 'website' : 'name_only') + '"}';
return [{ json: {
  source: usable ? 'website' : 'name_only',
  geminiBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json' } },
} }];

// Gemini text -> our JSON. Anything unreadable becomes {error} so Odoo shows its offline message.
const INDUSTRIES = ['ecommerce', 'finance', 'healthcare', 'telecom', 'tech', 'other', 'unknown'];
const item = $input.first().json;
const source = $('Build prompt').first().json.source;
try {
  const raw = item.candidates[0].content.parts[0].text;
  const answer = JSON.parse(raw.replace(/```(json)?/gi, '').trim());
  const industry = String(answer.industry || 'unknown').trim().toLowerCase();
  return [{ json: {
    industry: INDUSTRIES.includes(industry) ? industry : 'unknown',
    summary: String(answer.summary || '').trim(),
    support_channels: String(answer.support_channels || 'unknown').trim(),
    company_size: String(answer.company_size || 'unknown').trim(),
    source,
  } }];
} catch (e) {
  return [{ json: { error: 'Gemini answer unreadable: ' + ((item.error && item.error.message) || e.message) } }];
}
